/* Transparent record arithmetic and writing checks; no admissions probability model. */
const AdvisingCore=(()=>{
 const points=g=>{const s=String(g??'').trim().toUpperCase(),map={A:4,'A-':3.7,'B+':3.3,B:3,'B-':2.7,'C+':2.3,C:2,'C-':1.7,'D+':1.3,D:1,'D-':0.7,F:0,E:0};return Object.hasOwn(map,s)?map[s]:s!==''&&Number.isFinite(+s)&&+s>=0&&+s<=4?+s:null};
 function gpas(courses,excluded=[]){const groups=new Map(),seen=new Set();let omitted=0;for(const c of [...courses,...excluded,...courses.flatMap(c=>(c.creditOrigins||[]).filter(o=>o.institution===c.institution&&c.units).map(o=>({...o,units:c.units,completed:true})))]){const grade=points(c.grade),units=c.units||(c.imported?'Quarter':null);if(grade===null||!units||!(+c.credits>0)||c.creditType==='transfer'||c.completed!==true&&!['failed','superseded'].includes(c.attemptStatus)&&!['F','E','0','0.0'].includes(String(c.grade).trim().toUpperCase())){omitted++;continue}const id=[c.institution,c.code,c.term||'',c.grade,c.credits,units].join('|');if(seen.has(id))continue;seen.add(id);const k=[c.institution,units].join('|'),g=groups.get(k)||{institution:c.institution,units,credits:0,qualityPoints:0,attempts:0};g.credits+=+c.credits;g.qualityPoints+=grade*+c.credits;g.attempts++;groups.set(k,g)}return{groups:[...groups.values()].map(g=>({...g,gpa:g.qualityPoints/g.credits})),omitted}}
 function targetGrade(g,target,credits){if(!g||!Number.isFinite(+target)||+target<0||+target>4||!Number.isFinite(+credits)||+credits<=0)return null;const needed=(+target*(g.credits+ +credits)-g.qualityPoints)/+credits;return{needed,possible:needed<=4,minimum:Math.max(0,needed),scenarios:Array.from({length:9},(_,i)=>({grade:i/2,gpa:(g.qualityPoints+i/2*+credits)/(g.credits+ +credits)}))}}
 function writing(text,prompt,limit){const words=String(text||'').trim().split(/\s+/).filter(Boolean),paragraphs=String(text||'').trim().split(/\n\s*\n/).filter(Boolean);const strengths=[],improve=[];if(words.length)strengths.push('You have a draft to work from: '+words.length+' words.');if(paragraphs.length>1)strengths.push('Your draft has paragraph breaks to help readers follow it.');else if(words.length>100)improve.push('Break the draft into paragraphs with one clear purpose each.');if(!prompt?.trim())improve.push('Add the exact application prompt before checking relevance.');if(+limit>0&&words.length>+limit)improve.push('Cut '+(words.length- +limit)+' words to meet your entered word limit.');if(words.length&&words.length<100)improve.push('This is a short draft. Check whether you have answered each part of the actual prompt.');if(words.some(w=>w.length>0))improve.push('Review one concrete example: what you did, its outcome, and what you learned. A writing check cannot verify those facts.');return{words:words.length,paragraphs:paragraphs.length,strengths,improve}}
 return{points,gpas,targetGrade,writing};
})();if(typeof module!=='undefined')module.exports=AdvisingCore;
